import React from "react";
import "./Category.css";
import CategoryCard from "./CategoryCard";

// Import images
import bags from "../assets/bags.jpg";
import clothes from "../assets/clothes.jpg";
import makeup from "../assets/makeup.jpg";
import electronics from "../assets/electronics.jpg";
import footwear from "../assets/Footwear.jpg";
import decor from "../assets/decor.jpg";

const Category = () => {
  const categories = [
    { title: "Bags", image: bags },
    { title: "Clothes", image: clothes },
    { title: "Makeup", image: makeup },
    { title: "Electronics", image: electronics },
    { title: "Footwear", image: footwear },
    { title: "Home Decor", image: decor },
  ];

  return (
    <div className="category-page">
      {/* Categories */}
      <section className="categories-section">
        <h2 className="section-heading">Shop by Category</h2>
        <div className="categories-grid">
          {categories.map((cat) => (
            <CategoryCard key={cat.title} image={cat.image} title={cat.title} />
          ))}
        </div>
      </section>

      {/* Footer */}
      <footer className="footer">
        <p>© 2025 Comparify. All Rights Reserved.</p>
        <div className="footer-links">
          <a href="#">Privacy Policy</a> | <a href="#">Terms of Service</a>
        </div>
      </footer>
    </div>
  );
};

export default Category;
